/*Table structure for table `bills` */

DROP TABLE IF EXISTS `bills`;

CREATE TABLE `bills` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bill_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_id` int(11) NOT NULL,
  `booking_id` int(11) DEFAULT NULL,
  `activity_rental_id` int(11) DEFAULT NULL,
  `motor_rental_id` int(11) DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `paid_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `status` enum('unpaid','partially_paid','paid','cancelled','refunded','void') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unpaid',
  `receipt_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issued_by` int(11) NOT NULL,
  `issued_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `cancellation_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `driver_license_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver_license_expiry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_verified_by` int(11) DEFAULT NULL,
  `license_verified_staff_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_verified_at` datetime DEFAULT NULL,
  `license_verification_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNVERIFIED',
  `license_flag_reason` text COLLATE utf8mb4_unicode_ci,
  `driver_license_restrictions` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designated_driver_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PH',
  `passport_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country_of_issuance` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foreign_license_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foreign_license_expiry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idp_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idp_expiry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idp_category_a` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `bill_number` (`bill_number`),
  KEY `fk_bill_booking` (`booking_id`),
  KEY `fk_bill_rental` (`activity_rental_id`),
  KEY `fk_bill_staff` (`issued_by`),
  KEY `idx_bills_customer` (`customer_id`),
  KEY `idx_bills_status` (`status`),
  CONSTRAINT `fk_bill_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`),
  CONSTRAINT `fk_bill_customer` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_bill_rental` FOREIGN KEY (`activity_rental_id`) REFERENCES `activity_rentals` (`id`),
  CONSTRAINT `fk_bill_staff` FOREIGN KEY (`issued_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=171 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `bills` */

