/*Table structure for table `motor_damage_assessments` */

DROP TABLE IF EXISTS `motor_damage_assessments`;

CREATE TABLE `motor_damage_assessments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rental_id` int(11) NOT NULL,
  `motor_id` int(11) NOT NULL,
  `customer_id` int(11) NOT NULL,
  `assessed_by` int(11) NOT NULL,
  `severity` enum('minor','moderate','major','total_loss') NOT NULL DEFAULT 'minor',
  `description` text NOT NULL,
  `photos` json NOT NULL,
  `estimated_repair_cost` decimal(10,2) NOT NULL,
  `charge_amount` decimal(10,2) NOT NULL,
  `status` enum('assessed','billed','waived','adjusted','settled') NOT NULL DEFAULT 'billed',
  `waived_by` int(11) DEFAULT NULL,
  `waived_at` datetime DEFAULT NULL,
  `waiver_reason` text,
  `bill_id` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_mda_rental` (`rental_id`),
  KEY `idx_mda_motor` (`motor_id`),
  KEY `idx_mda_customer` (`customer_id`),
  KEY `idx_mda_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4;

