/*Table structure for table `motorcycles` */

DROP TABLE IF EXISTS `motorcycles`;

CREATE TABLE `motorcycles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `motor_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `plate_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rental_rate` decimal(10,2) NOT NULL,
  `late_fee_hourly_rate` decimal(10,2) DEFAULT NULL,
  `rate_type` enum('hourly','daily') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `description` text COLLATE utf8mb4_unicode_ci,
  `image_url` text COLLATE utf8mb4_unicode_ci,
  `status` enum('AVAILABLE','RESERVED','RENTED','MAINTENANCE','INACTIVE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `motor_id` (`motor_id`),
  UNIQUE KEY `plate_number` (`plate_number`),
  KEY `idx_motor_status` (`status`),
  KEY `idx_motor_plate` (`plate_number`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `motorcycles` */

insert  into `motorcycles`(`id`,`motor_id`,`brand`,`model`,`type`,`plate_number`,`rental_rate`,`late_fee_hourly_rate`,`rate_type`,`description`,`image_url`,`status`,`created_at`,`updated_at`) values (1,'MOT-2026-0001','Honda','Click 125','Scooter','J23RP9','500.00',NULL,'daily','Smooth automatic 125cc scooter. Fuel efficient with spacious under-seat compartment.','/uploads/motor-1-1786977913695-78546.jpg','AVAILABLE','2026-08-17 15:53:16','2026-09-02 15:36:57'),(2,'MOT-2026-0002','Yamaha','Mio Sporty','Scooter','RB95F3','500.00',NULL,'daily','Lightweight and agile automatic scooter. Ideal for solo exploring in Batuan and Bohol.','/uploads/motor-2-1786978169712-22715.jpg','AVAILABLE','2026-08-17 15:53:16','2026-09-02 15:36:57'),(3,'MOT-2026-0003','Honda','Beat 110','Scooter','GH59F7','500.00',NULL,'daily','Economical 110cc automatic scooter with enhanced smart power engine.','/uploads/motor-3-1786977739387-95663.jpg','AVAILABLE','2026-08-17 15:53:16','2026-09-08 11:52:24'),(4,'MOT-2026-0004','Yamaha','NMAX 155','Maxi-Scooter','QY458KL','700.00',NULL,'daily','Premium 155cc maxi-scooter with ABS, dual-channel disc brakes, and superior ride comfort.','/uploads/motor-4-1787786028140-693.jpg','AVAILABLE','2026-08-17 15:53:16','2026-08-27 07:13:48'),(5,'MOT-2026-0005','Yamaha','Aerox 155','Sport Scooter','EX98K7','700.00',NULL,'daily','Sporty dynamic performance with VVA engine and aggressive handling.','/uploads/motor-5-1787785796128-98212.jpg','AVAILABLE','2026-08-17 15:53:16','2026-08-27 07:14:47'),(6,'MOT-2026-0006','Honda','Fazzio','Scooter','ED78R9','600.00',NULL,'daily','Nindot ni kaayo','/uploads/motor-mot-2026-0006-1787719436780-76525.jpg','AVAILABLE','2026-08-26 12:43:56','2026-09-08 16:15:05'),(7,'MOT-2026-0007','Honda','ADV 160','Scooter','GRW56P','800.00',NULL,'daily',NULL,'/uploads/motor-mot-2026-0007-1787797396749-4332.jpg','AVAILABLE','2026-08-27 10:23:16','2026-09-08 11:52:27');

/*Table structure for table `payments` */

DROP TABLE IF EXISTS `payments`;

CREATE TABLE `payments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bill_id` int(11) NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `method` enum('cash','card','ewallet') COLLATE utf8mb4_unicode_ci NOT NULL,
  `received_by` int(11) NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `receipt_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paid_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `receipt_number` (`receipt_number`),
  KEY `fk_payment_staff` (`received_by`),
  KEY `idx_payments_bill` (`bill_id`),
  CONSTRAINT `fk_payment_bill` FOREIGN KEY (`bill_id`) REFERENCES `bills` (`id`),
  CONSTRAINT `fk_payment_staff` FOREIGN KEY (`received_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

