/*Table structure for table `rooms` */

DROP TABLE IF EXISTS `rooms`;

CREATE TABLE `rooms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `room_number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `room_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `capacity` int(11) NOT NULL DEFAULT '1',
  `rate_per_night` decimal(10,2) NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'available',
  `description` text COLLATE utf8mb4_unicode_ci,
  `image_urls` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `room_number` (`room_number`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `rooms` */

insert  into `rooms`(`id`,`room_number`,`room_type`,`capacity`,`rate_per_night`,`status`,`description`,`image_urls`,`created_at`,`updated_at`) values (1,'101','Standard Twin',8,'1000.00','available','A breezy 8-bed mixed dorm featuring our signature hammock-style bunks. Includes personal lockers and shared bathroom access.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-09-08 21:33:56'),(2,'102','Female Dormitory',6,'800.00','available','A comfortable 6-bed female-only dorm. Features privacy curtains, reading lights, and air conditioning.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-09-03 09:58:38'),(3,'201','Private Standard Room',2,'900.00','available','A cozy private room with a double bed, private en-suite bathroom, and a small balcony overlooking the garden.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-09-03 09:24:59'),(4,'202','Hammock Suite',2,'1200.00','available','Our premium suite featuring a king-sized bed, an indoor lounge hammock, air conditioning, and a private sea-view balcony.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-09-03 10:21:40'),(5,'203','Family Room',4,'950.00','available','Spacious family room equipped with two queen beds, a mini-fridge, and a large private bathroom. Currently undergoing upgrades.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-08-26 20:24:12');

